// ============================================================
// CONFIGURATION
//
// Only edit these two lists when task restrictions change.
// Every Task Type not included here remains available everywhere.
// ============================================================

const LEAD_ONLY_TASK_TYPES = [
  'Schedule initial consultation',
  'Schedule sample collection',
  'Contact later',
  'Discovery call',
]

const DEAL_ONLY_TASK_TYPES = [
  'Consultation',
  'Nutrition consultation',
  'Concierge',
  'Sample collection',
  'Therapy',
  'Other consultation',
  'Send supplements',
  'Send probiotics',
  'Start CGM',
]


class CRMTask {
  async onRender() {
    await this.applyTaskTypeOptions()
  }

  async reference_doctype() {
    await this.applyTaskTypeOptions()
  }

  // ==========================================================
  // LOAD THE COMPLETE OPTION LIST FROM CRM TASK META
  // ==========================================================

  async getAllTaskTypes() {
    // Cache the untouched list so changing reference_doctype
    // does not progressively remove more options.
    if (this._allTaskTypes?.length) {
      return this._allTaskTypes
    }

    const meta = await this.getMeta('CRM Task')

    const taskTypeField = meta?.fields?.find(
      (field) => field.fieldname === 'custom_task_type',
    )

    let options = taskTypeField?.options || []

    // Depending on how meta was processed, options can arrive
    // either as a newline-separated string or as option objects.
    if (typeof options === 'string') {
      options = options.split('\n')
    }

    if (!Array.isArray(options)) {
      options = []
    }

    this._allTaskTypes = options
      .map((option) => {
        if (typeof option === 'string') {
          return option.trim()
        }

        if (option && typeof option === 'object') {
          return String(option.value || '').trim()
        }

        return ''
      })
      .filter(Boolean)

    return this._allTaskTypes
  }

  // ==========================================================
  // FILTER OPTIONS BY REFERENCE DOCTYPE
  // ==========================================================

  async applyTaskTypeOptions() {
    const allTaskTypes = await this.getAllTaskTypes()
    const referenceDoctype = this.doc.reference_doctype || ''

    let blockedTaskTypes = []

    if (referenceDoctype === 'CRM Lead') {
      // Leads may use Lead-only and common types,
      // but not Deal-only types.
      blockedTaskTypes = DEAL_ONLY_TASK_TYPES
    } else if (referenceDoctype === 'CRM Deal') {
      // Deals may use Deal-only and common types,
      // but not Lead-only types.
      blockedTaskTypes = LEAD_ONLY_TASK_TYPES
    } else {
      // Other reference doctypes may use only common types.
      blockedTaskTypes = [
        ...LEAD_ONLY_TASK_TYPES,
        ...DEAL_ONLY_TASK_TYPES,
      ]
    }

    const allowedTaskTypes = allTaskTypes.filter(
      (taskType) => !blockedTaskTypes.includes(taskType),
    )

    // Clear an existing value if it is invalid for the newly
    // selected reference doctype.
    if (
      this.doc.custom_task_type &&
      !allowedTaskTypes.includes(this.doc.custom_task_type)
    ) {
      this.doc.custom_task_type = ''
    }

    // The initial blank option is intentional. It prevents CRM
    // from silently treating the first real option as selected.
    this.setFieldProperty(
      'custom_task_type',
      'options',
      ['', ...allowedTaskTypes].join('\n'),
    )
  }
}

class CRMLead {
  onLoad() {
    this.setupLeadOwnerHighlight()
  }

  setupLeadOwnerHighlight() {
    const STYLE_ID = "crm-lead-owner-highlight-style"

    const MAIN_CLASS = "crm-lead-owner-highlight-main"
    const SIDEBAR_CLASS = "crm-lead-owner-highlight-sidebar"
    const HEADER_CLASS = "crm-lead-owner-highlight-header"

    const STATE_KEY = "__crmLeadOwnerHighlightState"

    const ownerLabels = new Set([
      "Vlastník potenciálního klienta",
      "Lead Owner",
    ])

    /*
     * Disconnect the observer created by the previous page load.
     */
    if (window[STATE_KEY]?.observer) {
      window[STATE_KEY].observer.disconnect()
    }

    /*
     * Create or update the styling.
     */
    let style = document.getElementById(STYLE_ID)

    if (!style) {
      style = document.createElement("style")
      style.id = STYLE_ID
      document.head.appendChild(style)
    }

    style.textContent = `
      /*
       * MAIN DATA FORM
       */
      .${MAIN_CLASS} {
        background: rgba(245, 158, 11, 0.14) !important;
        box-shadow: 0 0 0 2px #f59e0b !important;
        border-radius: 8px !important;
        transition:
          background-color 150ms ease,
          box-shadow 150ms ease;
      }

      .${MAIN_CLASS}:focus-within {
        background: rgba(245, 158, 11, 0.20) !important;
        box-shadow: 0 0 0 3px #f59e0b !important;
      }

      /*
       * RIGHT SIDEBAR
       */
      .${SIDEBAR_CLASS} {
        background: rgba(245, 158, 11, 0.14) !important;
        box-shadow: inset 0 0 0 2px #f59e0b !important;
        border-radius: 8px !important;
        transition:
          background-color 150ms ease,
          box-shadow 150ms ease;
      }

      .${SIDEBAR_CLASS}:focus-within {
        background: rgba(245, 158, 11, 0.20) !important;
        box-shadow: inset 0 0 0 3px #f59e0b !important;
      }

      /*
       * OWNER SELECTOR IN THE TOP HEADER
       *
       * An inset outline is used so its dimensions
       * and the neighbouring status control do not move.
       */
      .${HEADER_CLASS} {
        background: rgba(245, 158, 11, 0.14) !important;
        box-shadow: inset 0 0 0 2px #f59e0b !important;
        border-radius: 8px !important;
        color: #92400e !important;
        transition:
          background-color 150ms ease,
          box-shadow 150ms ease;
      }

      .${HEADER_CLASS}:hover,
      .${HEADER_CLASS}:focus-within {
        background: rgba(245, 158, 11, 0.20) !important;
        box-shadow: inset 0 0 0 3px #f59e0b !important;
      }

      .${HEADER_CLASS} span,
      .${HEADER_CLASS} div {
        color: #92400e !important;
      }

      /*
       * Label styling shared by the main field
       * and the right sidebar.
       */
      .${MAIN_CLASS} .text-ink-gray-5,
      .${MAIN_CLASS} label,
      .${SIDEBAR_CLASS} .text-ink-gray-5,
      .${SIDEBAR_CLASS} label {
        color: #92400e !important;
        font-weight: 600 !important;
      }
    `

    const normalizeText = (value) => {
      return String(value || "")
        .replace(/\*/g, "")
        .replace(/\s+/g, " ")
        .trim()
    }

    /*
     * Read the visible owner name from the Lead Owner field.
     *
     * For example:
     * Label: Lead Owner
     * Avatar: I
     * Value: Info
     *
     * The single-letter avatar is ignored.
     */
    const getOwnerDisplayName = (fieldContainer) => {
      const values = [...fieldContainer.querySelectorAll("*")]
        .filter((element) => element.children.length === 0)
        .map((element) => normalizeText(element.textContent))
        .filter((text) => {
          if (!text) {
            return false
          }

          if (ownerLabels.has(text)) {
            return false
          }

          if (text.length <= 1) {
            return false
          }

          return true
        })

      const uniqueValues = [...new Set(values)]

      uniqueValues.sort((a, b) => b.length - a.length)

      return uniqueValues[0] || null
    }

    /*
     * Find the owner selector displayed in the upper-right header.
     */
    const findHeaderOwnerControl = (ownerDisplayName) => {
      if (!ownerDisplayName) {
        return null
      }

      const ownerName = normalizeText(ownerDisplayName).toLowerCase()

      /*
       * First try interactive controls directly.
       */
      const interactiveCandidates = [
        ...document.querySelectorAll(
          "button, [role='button'], [role='combobox']"
        ),
      ]
        .filter((element) => {
          const rect = element.getBoundingClientRect()
          const text = normalizeText(element.textContent).toLowerCase()

          const isVisible =
            rect.width > 0 &&
            rect.height > 0 &&
            window.getComputedStyle(element).display !== "none"

          const isInTopHeader =
            rect.top >= 0 &&
            rect.bottom <= 110 &&
            rect.left > window.innerWidth * 0.55

          const hasSuitableSize =
            rect.width >= 45 &&
            rect.width <= 250 &&
            rect.height >= 24 &&
            rect.height <= 58

          const containsOwner =
            text === ownerName ||
            text.endsWith(` ${ownerName}`) ||
            text.includes(ownerName)

          return (
            isVisible &&
            isInTopHeader &&
            hasSuitableSize &&
            containsOwner
          )
        })
        .sort((a, b) => {
          /*
           * Prefer the smallest matching control.
           * This avoids selecting a large parent header container.
           */
          return (
            a.getBoundingClientRect().width -
            b.getBoundingClientRect().width
          )
        })

      if (interactiveCandidates.length) {
        return interactiveCandidates[0]
      }

      /*
       * Fallback for cases where the selector is rendered as
       * nested divs rather than a native button.
       */
      const textCandidates = [
        ...document.querySelectorAll("span, div"),
      ].filter((element) => {
        if (element.children.length > 0) {
          return false
        }

        const rect = element.getBoundingClientRect()
        const text = normalizeText(element.textContent).toLowerCase()

        return (
          text === ownerName &&
          rect.top >= 0 &&
          rect.bottom <= 110 &&
          rect.left > window.innerWidth * 0.55
        )
      })

      for (const textElement of textCandidates) {
        let currentElement = textElement

        for (let level = 0; level < 6; level += 1) {
          if (!currentElement) {
            break
          }

          const rect = currentElement.getBoundingClientRect()
          const styles = window.getComputedStyle(currentElement)
          const borderRadius = parseFloat(styles.borderRadius) || 0

          const isSuitableContainer =
            rect.width >= 45 &&
            rect.width <= 250 &&
            rect.height >= 24 &&
            rect.height <= 58 &&
            rect.top >= 0 &&
            rect.bottom <= 110 &&
            rect.left > window.innerWidth * 0.55 &&
            borderRadius >= 4

          if (isSuitableContainer) {
            return currentElement
          }

          currentElement = currentElement.parentElement
        }
      }

      return null
    }

    const highlightOwnerFields = () => {
      /*
       * Remove previous highlights before detecting
       * the current rendered elements again.
       */
      document
        .querySelectorAll(
          `.${MAIN_CLASS}, .${SIDEBAR_CLASS}, .${HEADER_CLASS}`
        )
        .forEach((element) => {
          element.classList.remove(
            MAIN_CLASS,
            SIDEBAR_CLASS,
            HEADER_CLASS
          )
        })

      const possibleLabels = document.querySelectorAll(
        ".field .text-ink-gray-5, .field label"
      )

      let ownerDisplayName = null

      possibleLabels.forEach((labelElement) => {
        const labelText = normalizeText(labelElement.textContent)

        if (!ownerLabels.has(labelText)) {
          return
        }

        const fieldContainer = labelElement.closest(".field")

        if (!fieldContainer) {
          return
        }

        const isRightSidebar = Boolean(
          fieldContainer.closest(
            ".sections.flex.flex-col.overflow-y-auto"
          )
        )

        if (isRightSidebar) {
          fieldContainer.classList.add(SIDEBAR_CLASS)
        } else {
          fieldContainer.classList.add(MAIN_CLASS)
        }

        /*
         * Read the owner name from either representation.
         */
        if (!ownerDisplayName) {
          ownerDisplayName = getOwnerDisplayName(fieldContainer)
        }
      })

      /*
       * Highlight the matching owner control in the top header.
       */
      const headerOwnerControl =
        findHeaderOwnerControl(ownerDisplayName)

      if (headerOwnerControl) {
        headerOwnerControl.classList.add(HEADER_CLASS)
      }
    }

    let updateScheduled = false

    const scheduleHighlight = () => {
      if (updateScheduled) {
        return
      }

      updateScheduled = true

      requestAnimationFrame(() => {
        updateScheduled = false
        highlightOwnerFields()
      })
    }

    /*
     * Reapply highlighting after Frappe CRM redraws:
     * - the page header;
     * - the Data tab;
     * - the right sidebar;
     * - the owner value.
     */
    const observer = new MutationObserver(() => {
      scheduleHighlight()
    })

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    })

    window[STATE_KEY] = {
      observer,
    }

    scheduleHighlight()
    setTimeout(scheduleHighlight, 250)
    setTimeout(scheduleHighlight, 750)
    setTimeout(scheduleHighlight, 1500)
  }
}

let crmObserver = null;


/**
 * Center popup notification
 */
function showCenterPopup(message, type = "success") {

    const popup = document.createElement("div");

    popup.innerText = message;

    popup.style.position = "fixed";
    popup.style.top = "50%";
    popup.style.left = "50%";
    popup.style.transform = "translate(-50%, -50%)";

    popup.style.padding = "18px 28px";
    popup.style.borderRadius = "12px";

    popup.style.fontSize = "16px";
    popup.style.fontWeight = "600";

    popup.style.color = "white";

    popup.style.zIndex = "99999";

    popup.style.boxShadow =
        "0 10px 30px rgba(0,0,0,0.25)";

    popup.style.background =
        type === "success"
            ? "#16a34a"
            : "#dc2626";

    popup.style.opacity = "0";

    popup.style.transition =
        "opacity 0.3s ease";

    document.body.appendChild(popup);

    // Fade in
    setTimeout(() => {
        popup.style.opacity = "1";
    }, 10);

    // Fade out
    setTimeout(() => {

        popup.style.opacity = "0";

        setTimeout(() => {
            popup.remove();
        }, 300);

    }, 1200);
}


/**
 * Inject reusable CSS once
 */
function injectCustomStyles() {

    if (
        document.getElementById(
            "custom-lead-btn-style"
        )
    ) {
        return;
    }

    const style = document.createElement("style");

    style.id = "custom-lead-btn-style";

    style.innerHTML = `

        .custom-convert-btn {
            background: #000 !important;
            color: #fff !important;
            border: 1px solid #000 !important;
            border-radius: 8px !important;
            transition: all 0.2s ease !important;
        }

        .custom-convert-btn:hover {
            opacity: 0.92;
            transform: translateY(-1px);
        }

    `;

    document.head.appendChild(style);
}


/**
 * Stable observer for custom button
 */
function setupButtonObserver() {

    if (crmObserver) {
        return;
    }

    injectCustomStyles();

    crmObserver = new MutationObserver(() => {

        const buttons = [
            ...document.querySelectorAll("button")
        ];


        /**
         * Find custom button
         */
        const customBtn = buttons.find(btn =>
            btn.innerText.includes(
                "Convert to Customer"
            )
        );

        if (!customBtn) {
            return;
        }


        /**
         * Apply styling once
         */
        if (!customBtn.dataset.enhanced) {

            customBtn.dataset.enhanced = "1";

            customBtn.classList.add(
                "custom-convert-btn"
            );
        }


        /**
         * Find New button
         */
        const newBtn = buttons.find(btn =>
            btn.innerText.trim() === "New"
        );

        if (!newBtn) {
            return;
        }

        const container = newBtn.parentElement;

        if (!container) {
            return;
        }


        /**
         * Move button to far right
         */
        const alreadyAtEnd =
            customBtn.parentElement ===
                container &&
            customBtn ===
                container.lastElementChild;

        if (!alreadyAtEnd) {

            container.appendChild(customBtn);
        }

    });


    crmObserver.observe(document.body, {
        childList: true,
        subtree: true
    });
}


/**
 * Cleanup observer
 */
window.addEventListener(
    "beforeunload",
    () => {

        if (crmObserver) {

            crmObserver.disconnect();

            crmObserver = null;
        }
    }
);


/**
 * Main CRM form hook
 */
function setupForm({ doc, call }) {

    const isConverted =
        doc.status === "Converted" ||
        doc.converted === 1;


    /**
     * Hide button if already converted
     */
    if (isConverted) {

        return {
            actions: []
        };
    }


    /**
     * Start observer
     */
    setupButtonObserver();


    return {
        actions: [
            {
                label: "Convert to Customer",

                variant: "solid",

                onClick: async () => {

                    try {

                        await call(
                            "create_customer_from_lead",
                            {
                                lead_id: doc.name
                            }
                        );

                        showCenterPopup(
                            "Lead converted successfully",
                            "success"
                        );

                        // Reload after popup
                        setTimeout(() => {
                            window.location.reload();
                        }, 1500);

                    } catch (e) {

                        showCenterPopup(
                            e?.message ||
                            "Conversion failed",
                            "error"
                        );
                    }
                }
            }
        ]
    };
}

function setupForm({ doc }) {

    function hideConvertButton() {

        const header =
            document.getElementById("app-header");

        if (!header) {
            return;
        }

        const convertButton =
            Array.from(
                header.querySelectorAll("button")
            ).find(btn =>
                btn.textContent.trim() ===
                "Convert to Deal"
            );

        if (convertButton) {

            convertButton.style.display =
                "none";

            console.log(
                "Convert to Deal hidden"
            );
        }
    }

    // Initial run
    hideConvertButton();

    // Frappe rerender protection
    setTimeout(hideConvertButton, 500);

    setTimeout(hideConvertButton, 1000);

    setTimeout(hideConvertButton, 2000);

    return {
        actions: [],
    };
}

function setupForm({ doc }) {

    setTimeout(() => {

        // Prevent duplicate button
        if (document.getElementById("custom-view-leads-btn")) {
            return;
        }

        // Find Delete button
        const buttons = document.querySelectorAll("button");

        let deleteButton = null;

        buttons.forEach(btn => {
            if (btn.innerText.trim() === "Delete") {
                deleteButton = btn;
            }
        });

        if (!deleteButton) {
            return;
        }

        // Create button
        const btn = document.createElement("button");

        btn.id = "custom-view-leads-btn";

        btn.innerText = "View Leads";

        // Copy ALL classes from Delete button
        btn.className = deleteButton.className;

        // Override colors to black
        btn.style.background = "#111111";
        btn.style.color = "white";
        btn.style.borderColor = "#111111";
        btn.style.marginLeft = "8px";

        // Hover effect
        btn.onmouseenter = () => {
            btn.style.background = "#000000";
            btn.style.borderColor = "#000000";
        };

        btn.onmouseleave = () => {
            btn.style.background = "#111111";
            btn.style.borderColor = "#111111";
        };

        // Click action
        btn.onclick = () => {
            window.location.href =
                `/app/crm-lead?custom_contact=${doc.name}`;
        };

        // Insert next to Delete
        deleteButton.parentNode.insertBefore(
            btn,
            deleteButton.nextSibling
        );

    }, 1000);

    return {
        actions: []
    };
}

